Our ESLint 10 flat config still lints the generated files in src/generated and the legacy folder. Why does `ignores` not work, and how do I fix it?

```js
// eslint.config.js
import js from "@eslint/js";
import { defineConfig } from "eslint/config";

export default defineConfig([
  {
    files: ["**/*.js"],
    ignores: ["src/generated/", "legacy/"],
    plugins: { js },
    extends: ["js/recommended"],
  },
]);
```

Our custom ESLint rule worked on ESLint 8 and now crashes on ESLint 10 with `context.getScope is not a function`. Update it to current APIs.

```js
module.exports = {
  create(context) {
    const sourceCode = context.getSourceCode();
    return {
      Identifier(node) {
        if (context.getFilename().endsWith('.test.js')) return;
        const scope = context.getScope();
        const ref = scope.references.find((r) => r.identifier === node);
        if (ref && !ref.resolved) {
          context.report({ node, message: 'Undeclared ' + node.name, fix: (fixer) => fixer.insertTextBefore(node, 'window.') });
        }
      },
    };
  },
};
```
